-- Read-only installation receipt. Never returns a session token, device proof,
-- access code, email, or private workflow row.
select jsonb_build_object(
 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'hash',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'search_path',p.proconfig,'anon_execute',has_function_privilege('anon',p.oid,'execute'),'app_execute',has_function_privilege('authenticated',p.oid,'execute'),'service_execute',has_function_privilege('service_role',p.oid,'execute')) order by p.oid::regprocedure::text) from pg_proc p where p.pronamespace='business_auth'::regnamespace or p.oid=any(array['studio_workflow.context(uuid)'::regprocedure,'public.studio_role()'::regprocedure,'public.studio_bind_member(text)'::regprocedure,'public.studio_set_device(uuid,text)'::regprocedure,'public.resolve_media_delivery(text,text,text)'::regprocedure,'public.triniti_admin_provision(uuid,uuid,uuid,text,jsonb,text)'::regprocedure]) or (p.pronamespace='public'::regnamespace and p.proname in('business_session_allowed','business_auth_request_guard','triniti_business_signin_check','triniti_business_owner_access','triniti_business_finish_signin','triniti_business_cancel_signin'))),
 'private_tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'policies',(select count(*) from pg_policy where polrelid=c.oid),'anon_access',has_table_privilege('anon',c.oid,'select,insert,update,delete'),'app_access',has_table_privilege('authenticated',c.oid,'select,insert,update,delete'),'service_access',has_table_privilege('service_role',c.oid,'select,insert,update,delete')) order by c.relname) from pg_class c where c.relnamespace='business_auth'::regnamespace and c.relkind='r'),
 'policies',(select jsonb_agg(jsonb_build_object('table',c.oid::regclass::text,'permissive',p.polpermissive,'roles',p.polroles,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by c.oid::regclass::text) from pg_policy p join pg_class c on c.oid=p.polrelid where polname='business_session_required'),
 'triggers',(select jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid)) order by tgname) from pg_trigger where not tgisinternal and tgfoid in(select oid from pg_proc where pronamespace='business_auth'::regnamespace)),
 'request_hook',(select rolconfig from pg_roles where rolname='authenticator'),
 'new_counts',jsonb_build_object('accounts',(select count(*) from business_auth.accounts),'owner_seats',(select count(*) from business_auth.owner_seats),'device_keys',(select count(*) from business_auth.device_keys),'grants',(select count(*) from business_auth.grants),'sessions',(select count(*) from business_auth.sessions),'attempts',(select count(*) from business_auth.attempts),'events',(select count(*) from business_auth.events)),
 'data_counts',jsonb_build_object('auth_users',(select count(*) from auth.users),'auth_sessions',(select count(*) from auth.sessions),'profiles',(select count(*) from public.profiles),'business_profiles',(select count(*) from public.profiles where account_type='business'),'business_members',(select count(*) from public.business_access_members),'business_devices',(select count(*) from public.business_devices),'studio_bindings',(select count(*) from public.studio_session_members),'storage_objects',(select count(*) from storage.objects),'staff',(select count(*) from public.admin_users),'pending_provisions',(select count(*) from admin_ops.provisions where completed_at is null)),
 'buckets',(select jsonb_agg(jsonb_build_object('id',id,'public',public) order by id) from storage.buckets where id in('chat-media','chat-files','post-media','story-media','media'))
);
